<?php require __DIR__ . '/includes/config.php';if($_SERVER['REQUEST_METHOD']==='POST'){if($_POST['password']!==$_POST['password_confirmation']){flash('danger','Passwords do not match.');}else{$s=$pdo->prepare('INSERT INTO users (name,email,password) VALUES (?,?,?)');try{$s->execute([trim($_POST['name']),trim($_POST['email']),password_hash($_POST['password'],PASSWORD_DEFAULT)]);flash('success','Account created. Please sign in.');redirect('login.php');}catch(PDOException $e){flash('danger','That email is already registered.');}}}$pageTitle='Create account';require __DIR__ . '/includes/header.php'; ?><section class="container py-5"><div class="row justify-content-center"><div class="col-md-5"><div class="panel"><div class="eyebrow">Join Nexa</div><h1 class="h2 my-3">Create account</h1><form method="post"><label class="form-label">Name</label><input required name="name" class="form-control mb-3"><label class="form-label">Email</label><input required type="email" name="email" class="form-control mb-3"><label class="form-label">Password</label><input required type="password" name="password" class="form-control mb-3"><label class="form-label">Confirm password</label><input required type="password" name="password_confirmation" class="form-control mb-4"><button class="btn btn-dark w-100">Create account</button></form></div></div></div></section><?php require __DIR__ . '/includes/footer.php'; ?>